"use client";

// Local, in-browser playback of notification sounds. Built-in tones are generated by
// scripts/make_tones.py and shipped in /public/sounds. Custom sounds are served by the API.

export const BUILTIN_LABELS: Record<string, string> = {
  chime: "Chime",
  bell: "Bell",
  pulse: "Pulse",
  alert: "Alert (urgent)",
  soft: "Soft tap",
};

export function soundUrl(ref: string): string | null {
  if (ref.startsWith("builtin:")) return `/sounds/${ref.slice(8)}.wav`;
  if (ref.startsWith("upload:")) return `/api/notifications/sounds/${ref.slice(7)}`;
  return null;
}

let current: HTMLAudioElement | null = null;

export async function playSound(ref: string, volume = 1): Promise<HTMLAudioElement | null> {
  const url = soundUrl(ref);
  if (!url) return null;
  stopSound();
  const a = new Audio(url);
  a.volume = Math.max(0, Math.min(1, volume));
  current = a;
  try {
    await a.play();
  } catch {
    // Autoplay can be blocked until the user interacts with the page; nothing else to do.
    return null;
  }
  return a;
}

export function stopSound() {
  if (current) {
    current.pause();
    current.currentTime = 0;
    current = null;
  }
}

export function inQuietHours(start: string | null, end: string | null, tz: string): boolean {
  if (!start || !end) return false;
  const now = new Intl.DateTimeFormat("en-GB", { timeZone: tz, hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).format(new Date());
  return start < end ? now >= start && now < end : now >= start || now < end;
}
